import 'package:autohub_core/src/values/money.dart';
import 'package:flutter_test/flutter_test.dart';

/// Ported case-for-case from `backend/tests/AutoHub.Tests.Unit/SharedKernel/MoneyTests.cs`.
///
/// The port is the point. Every one of these is a number a dealer can see on a payout screen and
/// compare against a statement generated by the C# code, and a phone that rounds differently is a
/// support call that nobody can close.
void main() {
  group('construction', () {
    test('rupees convert to paise', () {
      expect(Money.fromRupees(847350).minorUnits, 84735000);
    });

    test('a major-unit string parses exactly, grouping commas and all', () {
      expect(Money.tryParseMajor('8,47,350').valueOrNull, Money.fromRupees(847350));
      expect(Money.tryParseMajor('100.50').valueOrNull, const Money.fromMinorUnits(10050));
      expect(Money.tryParseMajor('-100').valueOrNull, Money.fromRupees(-100));
    });

    test('an amount it cannot represent exactly is refused, not rounded', () {
      // Sub-paise precision is where reconciliation breaks. Better a field error at the boundary
      // than a silent half-paisa that only surfaces at month-end close.
      final result = Money.tryParseMajor('100.005');

      expect(result.errorCode, 'money.not_representable');
      expect(result.valueOrNull, isNull);
    });

    test('empty and non-numeric input carry distinguishable codes', () {
      expect(Money.tryParseMajor('').errorCode, 'money.required');
      expect(Money.tryParseMajor('lakh').errorCode, 'money.malformed');
    });
  });

  group('arithmetic', () {
    test('combining two currencies is refused rather than silently wrong', () {
      final rupees = Money.fromRupees(1000);
      final dollars = Money.fromMajorUnits(1000, Currency.usd);

      expect(() => rupees + dollars, throwsStateError);
      expect(() => rupees.compareTo(dollars), throwsStateError);
    });

    test('a rate produces exact minor units', () {
      // 2% auction commission on ₹8,47,350, then 18% GST on that commission.
      final commission =
          const Money.fromMinorUnits(84735000).multiplyByRate(Rate.fromWire(0.02));
      expect(commission.minorUnits, 1694700);

      final gst = const Money.fromMinorUnits(1694700).multiplyByRate(Rate.fromWire(0.18));
      expect(gst.minorUnits, 305046);
    });

    test("a rate off the wire is exact, not the double's binary expansion", () {
      expect(Rate.fromWire(0.02), Rate.ratio(1, 50));
      expect(Rate.fromWire(0.18), Rate.ratio(9, 50));
      expect(Rate.fromWire(0.185), Rate.ratio(37, 200));
      expect(Rate.fromWire(2), Rate.ratio(2, 1));
      expect(Rate.percent(18), Rate.fromWire(0.18));
      expect(Rate.basisPoints(250), Rate.fromWire(0.025));
    });

    test('the default rounding is bankers, not away-from-zero', () {
      // Half a paisa rounds to even. Always-up quietly transfers real money to the platform across
      // a million transactions, which is the kind of thing auditors find.
      expect(
        const Money.fromMinorUnits(5).multiplyByRate(Rate.ratio(1, 2)).minorUnits,
        2,
      );
      expect(
        const Money.fromMinorUnits(7).multiplyByRate(Rate.ratio(1, 2)).minorUnits,
        4,
      );
    });

    test('away-from-zero is available but must be asked for by name', () {
      expect(
        const Money.fromMinorUnits(5)
            .multiplyByRate(Rate.ratio(1, 2), rounding: Rounding.halfAwayFromZero)
            .minorUnits,
        3,
      );
      expect(
        const Money.fromMinorUnits(-5)
            .multiplyByRate(Rate.ratio(1, 2), rounding: Rounding.halfAwayFromZero)
            .minorUnits,
        -3,
      );
    });

    test('floor and ceiling go toward the named infinity, not toward zero', () {
      expect(
        const Money.fromMinorUnits(-5).multiplyByRate(Rate.ratio(1, 2), rounding: Rounding.floor).minorUnits,
        -3,
      );
      expect(
        const Money.fromMinorUnits(-5)
            .multiplyByRate(Rate.ratio(1, 2), rounding: Rounding.ceiling)
            .minorUnits,
        -2,
      );
    });

    test('a negative amount rounds symmetrically under bankers rounding', () {
      expect(
        const Money.fromMinorUnits(-5).multiplyByRate(Rate.ratio(1, 2)).minorUnits,
        -2,
      );
      expect(
        const Money.fromMinorUnits(-7).multiplyByRate(Rate.ratio(1, 2)).minorUnits,
        -4,
      );
    });
  });

  group('allocate', () {
    test('distributes the remainder so the parts sum to the whole', () {
      // ₹100.00 three ways is the canonical example: naive division gives ₹99.99.
      final parts = Money.fromRupees(100).allocate(<int>[1, 1, 1]);

      expect(parts.map((part) => part.minorUnits), <int>[3334, 3333, 3333]);
      expect(_sum(parts), Money.fromRupees(100));
    });

    test('respects uneven ratios and still balances', () {
      const total = Money.fromMinorUnits(84735000);

      final parts = total.allocate(<int>[70, 20, 10]);

      expect(_sum(parts), total);
      expect(parts[0].minorUnits, greaterThan(parts[1].minorUnits));
    });

    test('balances negative amounts too', () {
      // Refunds and credit notes travel as negative money and must still reconcile.
      final refund = Money.fromRupees(-100);

      expect(_sum(refund.allocate(<int>[1, 1, 1])), refund);
    });

    test('a zero ratio takes nothing and does not break the balance', () {
      final parts = const Money.fromMinorUnits(10000).allocate(<int>[0, 1, 1]);

      expect(parts[0], const Money.fromMinorUnits(0));
      expect(_sum(parts), const Money.fromMinorUnits(10000));
    });

    test('refuses ratios it cannot allocate against', () {
      expect(() => Money.fromRupees(100).allocate(<int>[]), throwsArgumentError);
      expect(() => Money.fromRupees(100).allocate(<int>[0, 0]), throwsArgumentError);
      expect(() => Money.fromRupees(100).allocate(<int>[1, -1]), throwsArgumentError);
    });
  });

  group('clamp', () {
    test('applies floor and cap', () {
      expect(
        Money.fromRupees(50).clamp(floor: Money.fromRupees(199)),
        Money.fromRupees(199),
      );
      expect(
        Money.fromRupees(90000).clamp(cap: Money.fromRupees(25000)),
        Money.fromRupees(25000),
      );
    });
  });

  group('currency', () {
    test('an unknown code is null rather than a throw at the decode seam', () {
      expect(Currency.tryFromCode('inr'), Currency.inr);
      expect(Currency.tryFromCode('XYZ'), isNull);
      expect(() => Currency.fromCode('XYZ'), throwsArgumentError);
    });
  });
}

Money _sum(List<Money> parts) => parts.fold(Money.zeroInr, (a, b) => a + b);
